"""Static review of the voice set-up. These checks READ the files; they do not run PHP and do not call ElevenLabs.
Run from the project folder:  python3 tests/check_voice_static.py"""
import os, re, sys, glob
HERE=os.path.abspath(os.path.join(os.path.dirname(__file__),'..'))
PUB=os.path.join(HERE,'public_html') if os.path.isdir(os.path.join(HERE,'public_html')) else HERE
TOP=HERE if os.path.isdir(os.path.join(HERE,'public_html')) else os.path.dirname(HERE)
rd=lambda p:open(p,encoding='utf-8',errors='ignore').read()
res=[]
def ok(n,c,d=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+((' | '+str(d)) if d else ''))
php=rd(os.path.join(PUB,'api','nandi-voice.php')); router=rd(os.path.join(PUB,'router.php')); htaccess=rd(os.path.join(PUB,'.htaccess'))
ok('Hindi voice ID maps to hi, English voice ID maps to en',re.search(r"'hi'\s*=>\s*'3AMU7jXQuQa3oRvRqUmb'",php) and re.search(r"'en'\s*=>\s*'1U02n4nD6AdIZ9CjF053'",php))
ok('Each voice ID appears exactly once (no other voice can be selected)',php.count('3AMU7jXQuQa3oRvRqUmb')==1 and php.count('1U02n4nD6AdIZ9CjF053')==1)
ok('The request body is read only for "lang" and "text" (no voice_id from the browser)',set(re.findall(r"\$input\['(\w+)'\]",php))=={'lang','text'})
ok('Browser code never sends a voice ID',not re.search(r'voice_?id|voiceId',rd(os.path.join(PUB,'assets','nandi.js')),re.I))
ok('API key is read from the ELEVENLABS_API_KEY environment variable',"getenv('ELEVENLABS_API_KEY')" in php)
ok('No API key literal anywhere in the project (sk_..., xi-api-key values)',not any(re.search(r'sk_[A-Za-z0-9]{20,}|xi-api-key:\s*[A-Za-z0-9]{20,}',rd(f)) for f in glob.glob(TOP+'/**/*',recursive=True) if os.path.isfile(f) and f.endswith(('.php','.js','.html','.bat','.ps1','.md','.txt','.example','.py','.xml'))))
ok('.env.example contains placeholders only',re.search(r'^ELEVENLABS_API_KEY=\s*$',rd(os.path.join(TOP,'.env.example')),re.M) is not None)
ok('No real .env file is in the package',not os.path.exists(os.path.join(TOP,'.env')) and not os.path.exists(os.path.join(PUB,'.env')))
ok('The private key file is not inside public_html',not os.path.exists(os.path.join(PUB,'private')) and not glob.glob(PUB+'/**/elevenlabs-key*.php',recursive=True))
ok('The key is never logged or echoed (error_log lines carry no key or text)',all(('$apiKey' not in l and '$text' not in l and '$input' not in l) for l in re.findall(r'error_log\([^;]*;',php)) and 'echo $apiKey' not in php and 'var_dump' not in php and 'print_r' not in php)
ok('Input is validated: method, same-origin, JSON type, body size, language, UTF-8, length',all(s in php for s in ["!== 'POST'",'nandi_same_origin()','application/json','NANDI_MAX_BODY_BYTES','isset(NANDI_VOICES[$lang])',"preg_match('//u'",'NANDI_MAX_TEXT_CHARS']))
ok('Rate limiting per visitor and a daily character cap exist, and addresses are stored only as hashes',all(s in php for s in ['NANDI_RATE_REQUESTS','NANDI_DAILY_CHAR_LIMIT','hash(\'sha256\'']))
ok('HTTPS certificate checking is on for the ElevenLabs call and redirects are off',all(s in php for s in ['CURLOPT_SSL_VERIFYPEER => true','CURLOPT_SSL_VERIFYHOST => 2','CURLOPT_FOLLOWLOCATION => false']))
ok('The ElevenLabs host and model can only be chosen from fixed lists',all(s in php for s in ['in_array($apiHost, NANDI_API_HOSTS','in_array($model, NANDI_MODELS']))
ok('Missing key and failures answer with clear error codes (not_configured, voice_timeout, voice_unavailable, voice_busy, rate_limited)',all(c in php for c in ["'not_configured'","'voice_timeout'","'voice_unavailable'","'voice_busy'","'rate_limited'"]))
ok('PHP errors are never shown to visitors',"ini_set('display_errors', '0')" in php)
ok('PHP file has no closing tag and no output before the opening tag (audio cannot be corrupted)',not php.rstrip().endswith('?>') and php.startswith('<?php'))
ok('Local router hides dotfiles, .env, tests, private and every PHP file except the voice endpoint',all(s in router for s in ["#(^|/)\\.#",'env|ini|log','tests|tools|private|php-config',"!== '/api/nandi-voice.php'"]))
csp_h=re.search(r'Content-Security-Policy "([^"]*)"',htaccess).group(1).replace('; upgrade-insecure-requests',''); csp_r=re.search(r'Content-Security-Policy: ([^"]*)"\);',router).group(1)
ok('Local router and .htaccess use the same Content Security Policy',csp_h==csp_r,'' if csp_h==csp_r else (csp_h,csp_r))
ok('CSP change is minimal: only media-src changed from none to blob: (needed to play the audio)',"media-src blob:" in csp_h and "default-src 'self'" in csp_h and "object-src 'none'" in csp_h and "connect-src 'self'" in csp_h and 'https:' not in csp_h.replace('https://fonts','').replace('https://www.google.com',''))
ok('.htaccess blocks router.php and voice-test.html on the live site',re.search(r'router\\\.php\|voice-test\\\.html',htaccess) is not None)
for f in ['START-NANDI.bat','SETUP-KEY.bat','setup-key.ps1']:
    b=open(os.path.join(TOP,f),'rb').read(); ok(f+': Windows (CRLF) line endings and plain ASCII',b.count(b'\r\n')>3 and b.count(b'\n')==b.count(b'\r\n') and all(c<128 for c in b))
bat=rd(os.path.join(TOP,'START-NANDI.bat'))
ok('START-NANDI.bat: runs PHP\'s own syntax check, never prints the key, only accepts four named settings from .env',' -l ' in bat and not re.search(r'echo[^\n]*%ELEVENLABS_API_KEY%',bat) and len(re.findall(r'if /i "%%A"==',bat))==4)
ok('START-NANDI.bat serves ONLY public_html (the .env stays outside the web folder)','-t "%SITE%"' in bat and '%ROOT%.env' in bat and 'SITE=%ROOT%public_html' in bat)
ps=rd(os.path.join(TOP,'setup-key.ps1')); ok('setup-key.ps1 hides what you type, validates the key shape, and writes only to .env beside the script',all(s in ps for s in ['-AsSecureString','-notmatch','Join-Path $root \'.env\'']))
ok('Browser voice fallback is still in Nandi',"new SpeechSynthesisUtterance" in rd(os.path.join(PUB,'assets','nandi.js')) and 'browserSpeak' in rd(os.path.join(PUB,'assets','nandi.js')))
ok('The four pages carry the current Nandi voice code (nothing out of date)',all('nandi-voice.php' in rd(os.path.join(PUB,p+'.html')) for p in ['index','treatments','studio','explore']))
mx=0
for m in re.finditer(r'a:\["((?:[^"\\]|\\.)*)","((?:[^"\\]|\\.)*)"\]',rd(os.path.join(PUB,'assets','nandi-brain.js'))): mx=max(mx,len(m.group(1)),len(m.group(2)))
ok('Information: longest scripted Nandi answer is %d characters (voice text is cut at 450, server accepts 500)'%mx,mx>0)
print('\n%d checks, %d passed, %d failed'%(len(res),sum(res),len(res)-sum(res))); sys.exit(0 if all(res) else 1)
